using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class ExternalApiTool
{
    [McpServerTool, Description("Fetches data from an external API for a given resource path.")]
    public static async Task<string> FetchExternalData(
        IHttpClientFactory httpClientFactory,
        [Description("The API resource path to query, e.g. 'users/1'.")] string resourcePath,
        CancellationToken cancellationToken = default)
    {
        using var client = httpClientFactory.CreateClient("ExternalApi");

        var response = await client.GetAsync(resourcePath, cancellationToken);
        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadFromJsonAsync<JsonElement>(cancellationToken);
        return JsonSerializer.Serialize(json, new JsonSerializerOptions { WriteIndented = true });
    }
}

using System.ComponentModel;
using ModelContextProtocol.Server;

[McpServerPromptType]
public static class SummarizePrompt
{
    [McpServerPrompt, Description("Generates a prompt that asks the model to summarize the provided text.")]
    public static IList<PromptMessage> Summarize(
        [Description("The text content to summarize.")] string content,
        [Description("Optional desired length: 'short', 'medium', or 'detailed'.")] string length = "medium")
    {
        var systemInstruction = length.ToLowerInvariant() switch
        {
            "short" => "Provide a 1-2 sentence summary.",
            "detailed" => "Provide a thorough, multi-paragraph summary covering all key points.",
            _ => "Provide a concise summary in one paragraph."
        };

        return
        [
            new(RoleKind.User,
                $"{systemInstruction}\n\nPlease summarize the following text:\n\n{content}")
        ];
    }
}

