using System.ComponentModel;
using ModelContextProtocol.Server;

[McpServerPromptType]
public static class SummarizePrompt
{
    [McpServerPrompt, Description("Generates a prompt that asks the model to summarize the provided text.")]
    public static IList<PromptMessage> Summarize(
        [Description("The text content to summarize.")] string content,
        [Description("Optional desired length: 'short', 'medium', or 'detailed'.")] string length = "medium")
    {
        var systemInstruction = length.ToLowerInvariant() switch
        {
            "short" => "Provide a 1-2 sentence summary.",
            "detailed" => "Provide a thorough, multi-paragraph summary covering all key points.",
            _ => "Provide a concise summary in one paragraph."
        };

        return
        [
            new(RoleKind.User,
                $"{systemInstruction}\n\nPlease summarize the following text:\n\n{content}")
        ];
    }
}

